(function () {
    cc.XXInviteItem = cc.Class({
        "extends": cc.Component,
        properties: {
            // sprite: cc.Sprite,
            on: cc.Button,
            off: cc.Button,
            lbNickName: cc.Label,
            lbBalance: cc.Label,
        },

        updateItem: function (item, itemID) {
            let accountInfo = item.Account;

            this.on.node.off("click");
            this.off.node.off("click");
            this.on.node.active = true;
            this.off.node.active = false;

            this.on.node.on("click", function () {
                this.on.node.active = false;
                this.off.node.active = true;
            }.bind(this));
            
            this.off.node.on("click", function () {
                this.on.node.active = true;
                this.off.node.active = false;
            }.bind(this));


            this.lbNickName.string = accountInfo.NickName;
            this.lbBalance.string = cc.Tool.getInstance().formatMoney(accountInfo.Balance * 8);
            this.item = item;
            this.itemID = itemID;
        },
    });
}).call(this);
